class ToDo:
  def __init__(self):
    self.tasks = []
  def add(self, task):
    self.tasks.append(task)

t = ToDo()
t.add('Study')
t.add('Sleep')
print(t.tasks)

class ToDo:
  def __init__(self):
    self.tasks = ['Study', 'Sleep']
  def complete(self, task):
    if task in self.tasks:
      self.tasks.remove(task)

t = ToDo()
t.complete('Study')
print(t.tasks)
